//! Embeds the factory presets (lane PBC of R1/S1): every `content/presets/**/*.patch.json` becomes an `include_str!`
//! entry of `$OUT_DIR/factory.rs`, so adding a preset needs no Rust edit, only the file (`cargo xtask preset-add`).
//!
//! The crate itself does no I/O (the root `clippy.toml` bans it); a build script reads the repository's files at
//! build time, the same job `include_str!` does for one named file, so it opts out of the bans here, with a reason.
//! Entries are sorted by relative path with `/` separators, so the generated file is the same on every platform.
//! Dot files and dot directories are skipped.
#![allow(
    clippy::disallowed_methods,
    reason = "a build script reads the repo's content and the build environment at build time; the crate does no I/O at run time"
)]
#![allow(
    clippy::print_stdout,
    reason = "cargo's build-script protocol is lines on stdout"
)]

use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::{env, fs};

const SUFFIX: &str = ".patch.json";

/// Collect `(relative path with '/', absolute path)` of every preset file under `dir`.
fn walk(root: &Path, dir: &Path, out: &mut Vec<(String, PathBuf)>) {
    let Ok(read) = fs::read_dir(dir) else {
        return;
    };
    for entry in read.flatten() {
        let path = entry.path();
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.starts_with('.') {
            continue;
        }
        if path.is_dir() {
            walk(root, &path, out);
        } else if name.ends_with(SUFFIX) {
            let rel = path
                .strip_prefix(root)
                .unwrap_or(&path)
                .components()
                .map(|c| c.as_os_str().to_string_lossy().into_owned())
                .collect::<Vec<_>>()
                .join("/");
            out.push((rel, path));
        }
    }
}

fn main() {
    let manifest = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").expect("cargo sets it"));
    let root = manifest.join("../../content/presets");
    // A directory is scanned for changes (files added, removed or edited) by cargo.
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed={}", root.display());
    let mut files = Vec::new();
    walk(&root, &root, &mut files);
    files.sort();
    let mut src = String::from(
        "// Generated by build.rs from content/presets/**/*.patch.json: do not edit.\n\
         /// `(path relative to content/presets with '/', file text)`, sorted by path.\n\
         pub static FACTORY_FILES: &[(&str, &str)] = &[\n",
    );
    for (rel, path) in &files {
        let abs = fs::canonicalize(path).unwrap_or_else(|_| path.clone());
        let _ = writeln!(
            src,
            "    ({rel:?}, include_str!({:?})),",
            abs.to_string_lossy()
        );
    }
    src.push_str("];\n");
    let out = PathBuf::from(env::var_os("OUT_DIR").expect("cargo sets it")).join("factory.rs");
    fs::write(&out, src).expect("write factory.rs");
}
